import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { ClientsPageClient } from './ClientsPageClient'
import type { ClientTag } from '@/components/clients/TagChip'

export const metadata: Metadata = {
  title: 'Clients — InkOS',
}

export default async function ClientsPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // S23 audit v1 — Clients page is the client list only. Tags moved to
  // /settings/tags, Consent Forms live in the sidebar, AI Design lives on
  // the individual client profile (or /ai-design).
  const [clientsResult, tagsResult] = await Promise.all([
    supabase
      .from('clients')
      .select('id, studio_id, first_name, last_name, email, phone, tags, total_spent_cents, total_sessions, last_visit_at, no_show_count, source, preferred_contact, archived_at, created_at, updated_at, date_of_birth, address, notes, referral_source, cancellation_count, loyalty_points, lifetime_value_cents, avg_session_value_cents, consent_minor, instagram_handle, tiktok_handle, website_url, is_banned, banned_reason, banned_at, banned_by, pronouns, avatar_url')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(50),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId)
      .order('name'),
  ])
  const initialClients = clientsResult.data ?? []
  const tagLibrary = (tagsResult.data ?? []) as ClientTag[]

  return (
    <PageShell>
      <PageHeader
        title="Clients"
        description="Manage client profiles, history, and notes."
      />

      <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
        <ClientsPageClient
          initialClients={initialClients}
          tagLibrary={tagLibrary}
        />
      </Suspense>
    </PageShell>
  )
}

